uiState.currentFilter.currentFilterString = newValue;

if (newValue.trim()) {
    const quickSearchConfig = tabConfig[uiState.currentTab.name].quickSearchDefaultConfig;
    uiState.currentFilter.advancedFilters = [{
        property: quickSearchConfig.property,
        operation: quickSearchConfig.operation,
        value: newValue
    }];
} else {
    uiState.currentFilter.advancedFilters = [];
}

loaders.loadActiveTab({ page: 1 });

const filters = newFilters || [];

uiState.currentFilter.currentFilterString = "";
uiState.currentFilter.advancedFilters = filters;
uiState.currentFilter.usingAdvancedFilters = filters.length > 0;

this.updateFilterChips(uiState, tabConfig, referenceData, additionalData);

loaders?.loadActiveTab({ page: 1 });

referenceData = referenceData ?? {};

const entityType = uiState.currentTab.name;
const service = tabConfig[entityType].service;
const definitions = service?.getFilterDefinitions ? service.getFilterDefinitions(additionalData?.requestingPage) : [];

// Process referenceData to flatten the stateMap
const processedReferenceData = {
    ...referenceData,
    stateMap: referenceData.stateMap
        ? Object.values(referenceData.stateMap).flat()
        : []
};

const result = await this.$modal.open("advanced-filter-modal", {
    resolve: {
        definitions: definitions,
        currentFilters: angular.copy(uiState.currentFilter.advancedFilters),
        referenceData: processedReferenceData
    }
});

if (result.result === "ok") {
    this.onAdvancedFilterUpdate(uiState, tabConfig, processedReferenceData, loaders, result.resolve.filters, additionalData);
}

return result;

referenceData = referenceData ?? {};

const currentTabName = uiState.currentTab.name;
const service = tabConfig?.[currentTabName]?.service;
const definitions = service?.getFilterDefinitions ? service.getFilterDefinitions(additionalData?.requestingPage) : [];

const result = this.filterService.generateChips(
    uiState.currentFilter.advancedFilters,
    definitions,
    referenceData,
    Object.fromEntries(
        this.en.modals.advancedFilterModal.dropdowns.FILTER_OPERATION.values
            .map(op => [op.value, op.label])
    )
);

uiState.currentFilter.chips = result.strings;
uiState.currentFilter.chipMap = result.map;

if (!Array.isArray(remainingStrings)) {
    return;
}

const newFilterState = remainingStrings
    .map(label => uiState.currentFilter.chipMap[label])

this.onAdvancedFilterUpdate(uiState, tabConfig, referenceData, loaders, newFilterState, additionalData);

uiState.currentFilter.currentFilterString = "";
uiState.currentFilter.advancedFilters = [];
uiState.currentFilter.usingAdvancedFilters = false;

this.updateFilterChips(uiState);

if (reload) {
    loaders.loadActiveTab({ page: 1 });
}
